import type {
  HostVariantImplementationWorkItemSnapshot,
  HostVariantWorkItemSnapshot,
} from '../agent-variants/contracts';
import {
  workItemCompleteCommand,
  workItemWorkerPrompt,
} from '../agent-variants/workItemBriefing';
import { EXECUTOR_LEASE_OWNER } from '../agent-variants/WorkerExecutorService';

export type StatusWithHostWork = {
  session?: {
    projectPath?: string;
  };
  variants?: {
    sessionId?: string;
    hostWork?: HostVariantWorkItemSnapshot[];
    workerRuntime?: string;
  };
};

export type HostWorkNextActionItem =
  HostVariantImplementationWorkItemSnapshot & {
    completeCommand: string;
    workerPrompt: string;
  };

export type NextActionWorkerHint = {
  binding: 'none';
};

export type HostWorkNextAction = {
  action: 'complete_host_variant_work';
  message: string;
  command: 'rivet variants complete';
  worker: NextActionWorkerHint;
  parallelism:
    | {
        recommended: false;
        strategy: 'direct';
        instructions: string;
      }
    | {
        recommended: true;
        strategy: 'one_worker_per_work_item';
        instructions: string;
      };
  sessionId?: string;
  workItems: HostWorkNextActionItem[];
};

const isImplementationWorkItem = (
  item: HostVariantWorkItemSnapshot,
): item is HostVariantImplementationWorkItemSnapshot =>
  item.kind === 'static_preview' ||
  item.kind === 'refine_variant' ||
  item.kind === 'code_gen';

export const buildHostWorkNextAction = (
  status: StatusWithHostWork,
  options?: { callerAgent?: string; callerModel?: string },
): HostWorkNextAction | null => {
  const hostWork = (status.variants?.hostWork ?? [])
    .filter(isImplementationWorkItem)
    .filter((item) => item.leaseOwner !== EXECUTOR_LEASE_OWNER);
  if (hostWork.length === 0) {
    return null;
  }
  const isSingleItem = hostWork.length === 1;
  const isDirect =
    isSingleItem &&
    (!hostWork[0].workerSelection?.model ||
      hostWork[0].workerSelection.model === options?.callerModel);
  const sessionId = status.variants?.sessionId;
  const completionCommandContext = {
    ...(status.session?.projectPath
      ? { projectPath: status.session.projectPath }
      : {}),
    ...(sessionId ? { sessionId } : {}),
  };
  const workItems: HostWorkNextActionItem[] = hostWork.map((item) => ({
    ...item,
    completeCommand: workItemCompleteCommand(
      item.workId,
      completionCommandContext,
    ),
    workerPrompt: sessionId
      ? workItemWorkerPrompt(sessionId, item)
      : `You are implementing one Rivet design variant ("${item.direction.label}"). Follow this work item's packet fields exactly (direction, mode, workspace) and finish by running: ${workItemCompleteCommand(item.workId, completionCommandContext)}`,
  }));
  return {
    action: 'complete_host_variant_work',
    message: isDirect
      ? 'Complete this variant work item directly in the current host, then run its completeCommand.'
      : 'Complete these independent variant work items concurrently. Each item MUST be reported the moment it finishes via its own completeCommand — never hold completions to batch them.',
    command: 'rivet variants complete',
    worker: { binding: 'none' },
    parallelism: isDirect
      ? {
          recommended: false,
          strategy: 'direct',
          instructions:
            'Avoid subagent startup for one item. Read the briefing file named in its workerPrompt, edit its assigned workspace directly, then run its completeCommand.',
        }
      : {
          recommended: true,
          strategy: 'one_worker_per_work_item',
          instructions: `Spawn every worker in this turn as native background subagents with the current permissions and approvals, one per item, passing that item's workerPrompt VERBATIM as the entire worker prompt. Inherit the current model unless workerSelection specifies a requested model. Use native model selection for that requirement; if unsupported, report that item failed before editing. Do not select a fixed-model agent definition or launch a detached provider CLI. Briefs are final and the briefing file contains the full packet and completion command. Each worker reports completion immediately. Denied or unavailable approval must be reported through the completion command without broader retries or server execution.`,
        },
    ...(status.variants?.sessionId
      ? { sessionId: status.variants.sessionId }
      : {}),
    workItems,
  };
};

export const withHostWorkNextAction = <T extends StatusWithHostWork>(
  status: T,
  options?: { callerAgent?: string; callerModel?: string },
): T & { nextAction?: HostWorkNextAction } => {
  const nextAction = buildHostWorkNextAction(status, options);
  return nextAction ? { ...status, nextAction } : status;
};
